// ZLEMAOpen opens a live [ZLEMAStream] on a warm-up history, oldest bar first,
// and returns it with its value at the last history bar, the value [Core.ZLEMA]
// writes there.
//
// inReal is the history; the parameters are those of [Core.ZLEMA].
//
// The error is [InsufficientHistory] for a history of at most
// [Core.ZLEMALookback] bars, [OutOfRangeEndIndex] for one longer than
// [IndexMax]+1 bars, and [BadParam] for a parameter out of range.
func (c *Core) ZLEMAOpen(inReal []float64, optInTimePeriod int) (*ZLEMAStream, float64, error) {
	if !fitsInt32(optInTimePeriod) {
		return nil, 0, BadParam
	}
	sp, err := c.zlemaOpenInternal(inReal, 0, int32(optInTimePeriod))
	if err != nil {
		return nil, 0, err
	}
	return sp, sp.cur_outReal, nil
}

// ZLEMAOpenAndFill opens a stream as [Core.ZLEMAOpen] does and also writes the
// outputs over the whole history, as [Core.ZLEMA] writes them for bars 0
// through len(inReal)-1, returning that range.
//
// Each output must hold len(inReal) minus [Core.ZLEMALookback] values and share
// no memory with an input or another output.
//
// The errors are those of [Core.ZLEMAOpen], and [BadParam] for an output that
// is empty, too short or sharing memory. A slice whose capacity a three-index
// expression cut, as slices.Clip does, can escape the sharing check.
func (c *Core) ZLEMAOpenAndFill(inReal []float64, optInTimePeriod int, outReal []float64) (*ZLEMAStream, OutRange, error) {
	if !fitsInt32(optInTimePeriod) {
		return nil, OutRange{}, BadParam
	}
	if len(inReal) > IndexMax+1 {
		return nil, OutRange{}, OutOfRangeEndIndex
	}
	lookback := int(c.zlemaLookback(int32(optInTimePeriod)))
	if lookback < 0 {
		return nil, OutRange{}, BadParam
	}
	outLen := max(len(inReal)-lookback, 0)
	if len(outReal) == 0 || len(outReal) < outLen {
		return nil, OutRange{}, BadParam
	}
	if sameStart(outReal, inReal) {
		return nil, OutRange{}, BadParam
	}
	if outLen > 0 && overlaps(outReal, inReal) {
		return nil, OutRange{}, BadParam
	}
	var outBegIdx, outNBElement int32
	sp, err := c.zlemaOpenAndFillInternal(inReal, 0, int32(optInTimePeriod), &outBegIdx, &outNBElement, outReal)
	if err != nil {
		return nil, OutRange{}, err
	}
	return sp, OutRange{BegIdx: int(outBegIdx), NBElement: int(outNBElement)}, nil
}

func zlemaStepTape(sp *ZLEMAStream, tape []float64, tapeBase, tapeMask int32, inReal float64) float64 {
	sp.prevMA = math.FMA(sp.emaBeta, sp.prevMA, float64(sp.optInK_1*(float64(2.0*inReal)-tape[(tapeBase-sp.ringCap_trailingIdx)&tapeMask])))
	sp.cur_outReal = sp.prevMA
	sp.outRangeCount++
	return sp.cur_outReal
}

func zlemaPeekTape(sp *ZLEMAStream, tape []float64, tapeBase, tapeMask int32, inReal float64) (float64, error) {
	var cur_outReal float64
	prevMA := sp.prevMA
	pkSlot0 := int32(-1)
	var pkVal0 float64
	pkSlot0 = tapeBase & tapeMask
	pkVal0 = inReal
	var _T2 float64
	if (tapeBase-sp.ringCap_trailingIdx)&tapeMask != pkSlot0 {
		_T2 = tape[(tapeBase-sp.ringCap_trailingIdx)&tapeMask]
	} else {
		_T2 = pkVal0
	}
	prevMA = math.FMA(sp.emaBeta, prevMA, float64(sp.optInK_1*(float64(2.0*inReal)-_T2)))
	cur_outReal = prevMA
	return cur_outReal, nil
}

func zlemaTapeDetach(sp *ZLEMAStream) int32 {
	reach := int32(0)
	sp.ring_trailingIdx_inReal = nil
	if sp.ringCap_trailingIdx > reach {
		reach = sp.ringCap_trailingIdx
	}
	return reach
}
